class ReadingScheme(BaseModel):
    """
    A reading scheme (ADR 0109): how a token's pinned reading is written, such as Jyutping, Pinyin, Baxter's Middle Chinese, sitelen Lasina, the Tiberian reading or Attic with its vowel lengths. Data in profiles/schemes/<id>.yaml: the pipeline reads it (nabu.schemes, which adds what voices do with readings) and core gets it through @nabu/schema/schemes. What a scheme can be used for follows from what it gives: shown as options or asked for (`answer`), typed (`typed`), heard as tones (`tones`).
    """

    model_config = ConfigDict(
        extra="forbid",
        frozen=True,
    )
    id: SchemeId
    names: Annotated[
        dict[LangTag, SchemeNames],
        Field(
            description="What the UI calls it and its tones, by the language they are written in (a BCP 47 tag; ADR 0109), as a course's names are: data, never app messages.",
            min_length=1,
        ),
    ]
    language: Annotated[
        LangTag,
        Field(
            description="The language whose sounds it writes: yue for Jyutping, cmn for Pinyin, ltc for Baxter's Middle Chinese. The audio round trip compares a language's characters by their readings where a scheme of that language can read written text (nabu.schemes)."
        ),
    ]
    lang: Annotated[
        ScriptedLangTag | None,
        Field(
            description="The language tag of its text where it stands on its own, as an option or an answer: yue-Latn-HK-jyutping. A profile's reading layer may tag its ruby otherwise (`lang`, ADR 0071)."
        ),
    ] = None
    answer: Annotated[
        OrthographyId | None,
        Field(
            description="The orthography its readings are in where a card offers them as options or asks for one (char-read, reading-disambiguation, transcribe; ADR 0098). A scheme without one is shown, never asked. Where an orthography has several such schemes, each is a reading tradition the learner may read in (ADR 0138: Pinyin, Jyutping and Baxter in Classical Chinese)."
        ),
    ] = None
    latin: Annotated[
        OrthographyId | None,
        Field(
            description="The orthography its readings are written in for a learner who cannot read the script yet (ADR 0133): an alphabet track's letters and words (a profile's `scriptTrack`) are tagged with it, and its profile grades them and ships in the bundle beside the course's own. A scheme whose own text is not Latin has a plug-in that writes a reading in it (nabu.schemes `latin`: Attic's χώρᾱ is chōrā); otherwise a reading is its own Latin (Schluessel)."
        ),
    ] = None
    bound: Annotated[
        Bound | None,
        Field(
            description="How a reading marks a word bound to the next, where the text binds it with a mark of its own (the Tiberian reading's final hyphen where a maqaf follows, ADR 0135): a reading ends with `mark` exactly where the next token holds `before` (`reading.bound`). A bound word is compared and filled in apart from a free one: it can read otherwise (unstressed: saʿar- before a maqaf, sáʿar free)."
        ),
    ] = None
    variants: Annotated[
        list[Variant2] | None,
        Field(
            description="Letters of the scheme that the script it reads writes alike, each list a set (ADR 0131): Schluessel's a, ä and ā all under alif. A reading card offers a word's reading with one of them traded for another of its set (bärdi for bardi), after the course's real homographs: what the script leaves for the reader to know. Compared in the scheme's `lang`, case kept.",
            min_length=1,
        ),
    ] = None
    ruby: Annotated[
        Literal["character", "word"],
        Field(
            description="What one ruby segment stands over where a profile shows the scheme as ruby (ADR 0129): each character (the default: a Han character's syllable, a logograph's word, a syllable of the script's own scheme) or the whole word, where the script's letters do not line up with the reading's (Schluessel's transliteration over a Chaghatay word in Arabic script, which leaves most vowels unwritten)."
        ),
    ] = "character"
    typed: Annotated[
        Typed | None,
        Field(
            description="A learner may type a reading in it (transcribe, ADR 0054). A typed answer is lowercased in `locale`, what may stand `between` syllables is dropped, and what is left must be syllables of this shape, end to end."
        ),
    ] = None
    typedByProfile: Annotated[
        Literal[True] | None,
        Field(
            description="A learner may type a reading in it as text of its `answer` orthography, graded by that orthography's profile (its marks, equivalences, typos and contrasts; ADR 0131): Schluessel's transliteration, whose words are not syllables of one shape. Asked only once the word's reading was read right by choice. A scheme with `typed` is graded by its syllables instead."
        ),
    ] = None
    tones: Annotated[
        Tones | None,
        Field(
            description="Its syllables carry tones (Jyutping's numbers): what marks one, and each tone's pitch, which the tone exercises, the device's tone scoring and the IPA voices take use."
        ),
    ] = None
    correspondences: Annotated[
        list[Correspondence] | None,
        Field(
            description="What this scheme writes of the lexical form, and what it loses (ADR 0148). It replaces `variants` at the switch (docs/migration-design.md); until then nothing reads it.",
            min_length=1,
        ),
    ] = None


